raw_rows = props.get("rates") or []
if isinstance(raw_rows, str):
	try:
		raw_rows = json.loads(raw_rows)
	except Exception:
		raw_rows = [line for line in raw_rows.split("\n") if line.strip()]
if not isinstance(raw_rows, list):
	raw_rows = []
rows = []
for raw in raw_rows:
	try:
		parts = [part.strip() for part in str(raw).split("|")]
		while len(parts) < 3:
			parts.append("")
		if parts[0] or parts[1]:
			rows.append(parts)
	except Exception:
		continue

records = []
for parts in rows:
	records.append({"item": parts[0], "scope": parts[1], "price": parts[2]})
component.rates = records
